  ('editions', 'ed-1', null, $fitr${"number": 1, "date": 1775606400000, "pages": 5, "title": "Skybridge Finally Available for Public Use?", "desc": "Rain-avoiding routes? New tiles? An upcoming café? FIWA welcomes students back after the holiday.", "contents": ["Front page", "More construction progress", "Internal FIWA News, part 1", "Internal FIWA News, part 2", "External News: Artemis II launch"], "pdf": "/editions/edition-1.pdf", "cover": "/editions/edition-1.jpg"}$fitr$::jsonb, to_timestamp(1793264611689/1000.0), to_timestamp(1793264611689/1000.0)),
