insert into public.fitr_records (coll, id, owner, data, created_at, updated_at) values
  ('articles', 'demo-ed5-building-h', null, $fitr${"section": "internal", "edition": 5, "title": "Building H Is Officially... Not Finished.", "deck": "Building H update sneak peek, version 2.0.26.", "author": "Mohamad Zahran", "coverImage": "/demo/edition-5/building-h-drone.jpg", "body": "\n<p>However, construction is underway, and the building appears to be about halfway finished! <i>(At least, I think so... I’m not entirely sure.)</i> Building H used to be a flat, dirt-covered plot of land next to the football field. Construction began last year, and, in my opinion, the building is looking great. Here’s an overview of its planned layout.</p>\n<ul>\n<li><b>First floor:</b> This floor will house a new mosque—sadly, not for us, but for the <i>akhwat</i>—which will occupy roughly two-thirds of the floor at the back. At the front, a new FIWA library will take up the remaining third.</li>\n<li><b>Second floor, first half:</b> Its purpose has not yet been confirmed. Some sources say it may contain rooms for “special” guests, but that has not been verified.</li>\n<li><b>Second floor, other half:</b> This area will be an outdoor space used for market days. On regular days, it may be used for something else. 👀</li>\n<li><b>Third floor:</b> This will be a multifunctional hall (<i>aula</i>).</li>\n</ul>\n<p>The third floor will also include two smaller, intermediate levels known as <b>mezzanine floors</b>. The multifunctional hall could be used as a basketball court. Current renderings show seating and stands along the sides.</p>\n<p>Rather than looking only at the future plans, let’s take a look at the <b>current progress:</b></p>\n<ul>\n<li>The framework for the <b>first floor</b> is finnaly complete, while the framework for the <b>second floor</b> is almost complete as well.</li>\n<li>The areas that look like the “third and fourth floors” from the outside, including the window designs, will actually be the mezzanine floors.</li>\n<li>Construction of the multifunctional hall is somehow already underway.</li>\n<li>According to Ustadz Luthfi, the building is expected to be completed next year, although the exact month has not yet been announced.</li>\n</ul>\n<h3>What building H currently looks like:</h3>\n<p><img class=\"rte-image\" src=\"/demo/edition-5/building-h-drone.jpg\" alt=\"Drone photo of Building H\" /></p>\n<p><i>*Drone photo of Building H taken above Building G*</i></p>\n<h3>Vision on what building H will look like:</h3>\n<p><img class=\"rte-image\" src=\"/demo/edition-5/building-h-render-court.jpg\" alt=\"3D render of Building H\" /></p>\n<p><i>*3D Render of the Vision on what Building H will look like (photo angle taken from the area between badminton field and the basketball field)</i></p>\n<p><img class=\"rte-image\" src=\"/demo/edition-5/building-h-render-entrance.jpg\" alt=\"3D render of Building H from the restaurant entrance\" /></p>\n<p><i>*3D Render of the Vision on what Building H will look like (photo angle taken from the restaurant‘s entrance)</i></p>\n", "tab": "new-1793264611683-1oyrb", "subtab": "", "visibility": "public", "lang": "en", "coverAspect": 1.7777777777777777, "coverFit": "crop"}$fitr$::jsonb, to_timestamp(1792544400000/1000.0), to_timestamp(1793264611702/1000.0)),
  ('articles', 'demo-ed5-water-treatment-plant', null, $fitr${"section": "internal", "edition": 5, "title": "Water Treatment Plant Moved & Improved!", "deck": "Water Treatment Plant (WTP) relocated to next to Gedung B, Water Capacity Increased, and all school water-related problems fixed since the 28th of September", "author": "Ammar Mufiid Johansyah", "coverImage": "/demo/edition-5/wtp-photo.jpg", "body": "\n<p>The Water Treatment Plant (WTP) has been relocated next to Building B, increasing water capacity. Most school water-related problems have reportedly been resolved since September 28.</p>\n<p>Ever since the student break began, members of the FIWA community have reported several water-related problems, including a strong chlorine-like smell and taste, water shortages during students’ shower times, and dirty water.</p>\n<p>The cause was the <b>relocation of the Water Treatment Plant (WTP)</b> from beneath Building C (known as the “C Basement”) to a location next to Building B. But why did this cause problems?</p>\n<p>During the relocation, some facilities had to be taken offline. After all, you cannot exactly use a water filter while it is being transported on a truck! According to Ustadz Fiyan, the school was supposed to use bottled water, such as Aqua, or other water sources during this period. However, FIWA uses around <b>115,000 liters of water per day</b>, so those alternatives may not have been enough to meet demand.</p>\n<p>The relocation was scheduled during the student break to prevent students from being left without water. However, the work took longer than the three days allocated for it. Moving the equipment and rerouting the pipes took time, which meant that students experienced water-related problems.</p>\n<p>Even after the relocation was completed, some issues remained. For context, FIWA draws its water from the Cisadane River. As the region transitions into the rainy season (see the weather article), rainfall becomes heavier. Rain falling directly on FIWA does not necessarily affect the water supply, but heavy rain upstream can affect the Cisadane River. When it rains upstream, mud, dirt, stones, and other debris can enter the water system and potentially clog the pipes. Sometimes, maintenance workers have to repair the pipes late at night to restore the water supply.</p>\n<p>According to Ustadz Fiyan, most of these issues—especially water shortages—had been resolved by September 28. One solution was to add more water tanks to the Akhwat’s water storage facility, which supplies water to our area first.</p>\n<p>Some students may still notice a slightly chlorine-like smell in the water. Such issues should be reported to the WTP team as soon as possible so they can be addressed. Ustadz Fiyan explained that new water tanks were added on September 28 to help meet the daily demand of 115,000 liters, and that most of the problems had been resolved. Alhamdulillah!</p>\n<p><img class=\"rte-image\" src=\"/demo/edition-5/wtp-photo.jpg\" alt=\"The Water Treatment Plant\" /></p>\n<p><i>*Photograph of the Water Treatment Plant behind the Security Post, on the left side of Gedung B.</i></p>\n<h3>How the Water Treatment Plant works, as told by Ustad Fiyan:</h3>\n<p><img class=\"rte-image\" src=\"/demo/edition-5/wtp-diagram.png\" alt=\"Diagram: intake, coagulation, sedimentation, filtration, disinfection, storage and taps\" /></p>\n", "tab": "new-1793264611683-1oyrb", "subtab": "", "visibility": "public", "lang": "en", "coverAspect": 1.7777777777777777, "coverFit": "crop"}$fitr$::jsonb, to_timestamp(1792544340000/1000.0), to_timestamp(1793264611703/1000.0)),
  ('articles', 'demo-ed5-transformer', null, $fitr${"section": "internal", "edition": 5, "title": "A New Transformer Has Arrived!", "deck": "A new transformer has Arrived, but will it be able to fix the problems?", "author": "Ammar Mufiid Johansyah", "coverImage": "/demo/edition-5/transformer.jpg", "body": "\n<p>Between September 18 and 20, during the student break, a brand-new transformer was installed outside the main gates of FIWA Ikhwan. According to Ustadz Fiyan in an interview, its purpose was to separate the electricity usage of the Ikhwan and Akhwat sectors. This is expected to make electricity use easier to manage and reduce afternoon power outages.</p>\n<p>The main cause of the blackouts is the power limit. According to Ustadz Fiyan, head of the Maintenance Division, PLN classifies FIWA as a low-usage customer. The school can draw a maximum of 200 amperes; if usage exceeds that limit, the power cuts out immediately.</p>\n<p>The biggest electricity consumers at FIWA are the air conditioners (ACs), followed by the water treatment plant. FIWA has carefully designed an AC schedule to keep electricity usage below the 200-ampere limit. However, students have frequently turned on the ACs outside the scheduled times, causing an overload and a subsequent power cut. This happens most often in the afternoon, which is also when we experience the most blackouts.</p>\n<p>FIWA’s schedule is specifically designed to address this problem. One measure is to arrange the AC schedules for the Akhwat and Ikhwan sectors so that they do not overlap.</p>\n<p><b>In a separate incident,</b> at around 3:20 p.m. on September 23, after the eighth period, smoke and sparks were seen coming from A2’s blue power box.</p>\n<p>Due to an unfortunate series of events (pun intended) involving incorrectly positioned circuitry, a battery that was already fully charged continued charging when it should have stopped. This caused the battery to swell and overheat. The potential fire was extinguished before it could escalate.</p>\n<p>Given these incidents, we urge all students to <b>please stop turning on the ACs outside the scheduled times</b>. If you do, the consequences affect the entire school. Are we tired of complaining about blackouts? Then this is one way to help prevent them. Sometimes, we have to sacrifice our personal comfort and convenience for the greater good of those around us.</p>\n<p><img class=\"rte-image\" src=\"/demo/edition-5/transformer.jpg\" alt=\"The new transformer beside the old one\" /></p>\n<p><i>*Image of the brand new installed Transformer on the right, alongside the old one on the left.</i></p>\n", "tab": "new-1793264611683-1oyrb", "subtab": "", "visibility": "public", "lang": "en", "coverAspect": 1.7777777777777777, "coverFit": "crop"}$fitr$::jsonb, to_timestamp(1792544280000/1000.0), to_timestamp(1793264611704/1000.0)),
  ('articles', 'demo-ed5-thunderstorm', null, $fitr${"section": "internal", "edition": 5, "title": "What a VERY thundery afternoon. huh?", "deck": "A big thunderstorm on the 26th of September, and weather updates", "author": "Ammar Mufiid Johansyah", "coverImage": null, "body": "\n<p>On 26 September 2026, a severe thunderstorm struck at around 4:45 p.m., while students were exercising and playing in the fields and swimming pool. Signs of a major storm had already appeared, including dark clouds and strong winds. The winds were so powerful that possibly hundreds or even thousands of seeds from the trees between the swimming pool and the football field were blown off and rained down.</p>\n<p>What followed was an extremely heavy thunderstorm, with lightning reportedly striking the ground every 15 seconds, according to some students. Furthermore, <i>BMKG</i> (<i>Badan Meteorologi, Klimatologi, dan Geofisika</i>) had issued four consecutive red warnings for thunderstorms, forecasting that the storms would occur between 11:00 p.m. on Saturday and 3:00 a.m. on Sunday. Unfortunately, it seems that the storm arrived much earlier than expected in Karihkil, striking at 4:45 p.m. instead of around 11:00 p.m.</p>\n<p><img class=\"rte-image\" src=\"/demo/edition-5/thunderstorm-warnings.jpg\" alt=\"Four consecutive red thunderstorm warnings\" /></p>\n<p><i>*Screenshot of the said 4 consecutive red-warnings-for-thunderstorms thingy. From Accuweather.com, which they got/derived From BMKG.</i></p>\n<p>The following day, Sunday, there was a light drizzle after Asr. The sun was still shining through the clouds, creating what many students would call <i>“the perfect rain”</i>—light and gentle, with the sunshine still peeking through the clouds.</p>\n<p>Looking at the bigger picture, although our area is technically still in the dry season, late September and early October mark a transitional period between the dry and rainy seasons. This transition is generally expected to settle in fully by late October or early November. That is why we have been experiencing frequent afternoon showers lately: we are in the transitional period, when this kind of weather is common.</p>\n<p>As of the week of 7 October, rainfall has been becoming increasingly frequent, following the typical pattern of the transition from the <i>dry to the rainy season</i>. We should all be grateful that we did not experience more severe weather during the dry season, even though <i>El Niño</i> was occurring, as explained in the weather article from our previous edition. <i>Alhamdulillah!</i></p>\n", "tab": "", "subtab": "", "visibility": "public", "lang": "en", "coverAspect": 1.7777777777777777, "coverFit": "crop"}$fitr$::jsonb, to_timestamp(1792544220000/1000.0), to_timestamp(1793264611705/1000.0)),
  ('articles', 'demo-ed5-wice', null, $fitr${"section": "internal", "edition": 5, "title": "To Malasyia, for WICE!", "deck": "FIWA Students head to Malasyia for WICE (World Invention Competition and Exhibition)", "author": "Ammar Mufiid Johansyah", "coverImage": null, "body": "\n<p>Around the 20th - 24th of September, 2026 (a few weeks ago), approximately <u>18</u> People went to Malaysia to go to a competition, which is <b>WICE!</b> (World Invention Competition and Exhibition).</p>\n<p>For those who dont know, WICE is an internationally recognised competition organised by IYSA (Indonesia Young Scientist Association) in collaboration with Universities in Malasyia like SEGi University and more, in which you guys make innovations &amp; projects and stuff, and essentially share it to the world!</p>\n<p>Alhamdullillah, FIWA won <b>3 SILVER</b> medals within WICE 2026. The names of the teams and the awards are on the right as you guys can see.</p>\n<p>The benefits of WICE is quite large, as claimed by the winners, since it’s an internationally recognised competition, if you won a gold medal or smth, it might be a big win for your portfolio! Yeah that’s it ig.</p>\n<p><img class=\"rte-image\" src=\"/demo/edition-5/wice-winners.jpg\" alt=\"FIWA's Instagram post of the WICE 2026 winners\" /></p>\n<p><i>*Image of the Post made by FIWA’s Instagram of the WICE 2026 Winners (from fiwa ofc)</i></p>\n", "tab": "", "subtab": "", "visibility": "public", "lang": "en", "coverAspect": 1.7777777777777777, "coverFit": "crop"}$fitr$::jsonb, to_timestamp(1792544160000/1000.0), to_timestamp(1793264611711/1000.0)),
  ('articles', 'demo-ed5-supercamp', null, $fitr${"coverAspect": 1.7777777777777777, "coverFit": "crop", "section": "internal", "title": "Supercamp: When and Where?", "deck": "Our next Supercamp is on 12 December 2026, and it is going to Saudi Arabia.", "author": "Kafa Althaf Habibi", "coverImage": "/demo/edition-5/supercamp.jpg", "body": "\n<p>After our last SUPERCAMP in January 2026, we are set to have another one on 12 December 2026. I wonder why our next Supercamp is also in 2026, just like the previous one, though...</p>\n<p>For our next Supercamp, we will travel to the holy city of Makkah to perform Umrah and visit Umm Al-Qura University. However, Ustadz Gufran is somewhat unsure about whether we should visit the university, since it is a women's university.</p>\n<p>Our next destination will be Madinah. There, we will take part in the UIM program and visit Kulliyat at-Taybah and Kulliyat al-Haram. As for Ha’il, we will most likely visit University Of Ha’il. After that, we will head to Jeddah, where we plan to visit King Abdulaziz University. We may also visit the University of Ta’if, although we have not yet confirmed which university we will be visiting for that part of the trip. Honestly, we’re not entirely sure yet!</p>\n<p><i>*Photograph taken during our last Supercamp in January 2026</i></p>\n", "edition": 5, "tab": "", "subtab": "", "visibility": "public", "lang": "en"}$fitr$::jsonb, to_timestamp(1792543800000/1000.0), to_timestamp(1793264611712/1000.0)),
  ('articles', 'demo-ed5-b1-rooms', null, $fitr${"coverAspect": 1.7777777777777777, "coverFit": "crop", "section": "internal", "title": "Ooooh.. new rooms in B1?", "deck": "The old laundry rooms in B1 are now dorm rooms for G12, and they are different.", "author": "Fathan Rasyid Athaya", "coverImage": "/demo/edition-5/b1-rooms.jpg", "body": "\n<p>Around early September or maybe around mid-late august, our lovely laundry room in B1 was moved to somewhere around FIWA, most likely in panorama bali. the used-to-be the laundry rooms in B1 were converted to standard dorm rooms for G12. In the grand scheme of things, it didn’t really affect its quality &amp; production speed, however, the rooms in B1 has a huge difference comparing to the other dorm rooms inside FIWA (B2, D1, D2) which is :</p>\n<ul>\n<li>No bunk beds! Yes, you read that right, G12 didn’t have to climb ladders just to get on their beds since all the beds are on the same height level.</li>\n<li>There’s some awesome learning desks, (with functioning chargers ofc) and also comes with chairs so they can study comfortably.</li>\n<li>Some mini storage drawers under the beds! and a mini locker right behind the beds.</li>\n<li>Another desk (a mini one) right under the mini lockers (the one behind the beds)</li>\n</ul>\n<p>All of these information are basically what standard G12 dorm rooms look like but I’m just gonna add it anyway to make this article longer..</p>\n<p>Well in my opinion, its really great for G12s and also FIWA can now fit a little more students. :)</p>\n<p><i>*Photograph of the new rooms in B1</i></p>\n", "edition": 5, "tab": "new-1793264611683-1oyrb", "subtab": "", "visibility": "public", "lang": "en"}$fitr$::jsonb, to_timestamp(1792543740000/1000.0), to_timestamp(1793264611715/1000.0)),
  ('articles', 'demo-ed5-robotics-lab', null, $fitr${"coverAspect": 1.7777777777777777, "coverFit": "crop", "section": "internal", "title": "Robotics Lab Opened?", "deck": "The Robotics Lab is finally open after 2 months of waiting.", "author": "Tubagus Attariza Rayyan Athaya & Fathan Rasyid Athaya", "coverImage": "/demo/edition-5/robotics-lab.jpg", "body": "\n<p>The Robotics Lab is finally open after 2 months of waiting, our suffering has ended! We can now 3D print, attend the Robotics extracurricular if you are attending the lesson, and the best part if you attend the Robotics extracurricular, there's two sessions!! The first one is at 13:30 till 14:30, and the second one is at 16:00 till 17:00.</p>\n<p>They also prepared Laptops for us to code, ALSO there’s a new functional table. It’s got wheels and if we combine two tables together, we can do long distance robot testing and also we got chargers? Do I hear it right? Yes I am, THERE ARE CHARGERS ON THE TABLES. It’s functioning right? ig idk. There's a new and better 3d printer aswell, the \"Bambu Lab A1\" specifically. Also it prints sooo much better according to the Ustadz.</p>\n<p>There's also a new set of \"Raspberry Pi\" mini computers, and it's already being supported by AI, mainly for more advanced robotic lessons. There's also new laptops, and fun fact, the laptops we used before is 5 human years old (That’s old), and we got some new specs, with some of them including having 16 GBs of RAM (Random-Access Memory) instead of 4 GB, and better memory, hopping from 256 GB to 512 GB. Last but not least, the CPUs are also amazingly better, upgraded from the \"Intel Core i3\" to \"Intel Core ULTRA 5\" (it even sounds cool by the name) (I agree).</p>\n<p><i>*Photograph of the Robotics Lab</i></p>\n", "edition": 5, "tab": "", "subtab": "", "visibility": "public", "lang": "en"}$fitr$::jsonb, to_timestamp(1792543680000/1000.0), to_timestamp(1793264611716/1000.0)),
  ('articles', 'demo-ed5-ayimun', null, $fitr${"coverAspect": 1.7777777777777777, "coverFit": "crop", "section": "internal", "title": "Being a Diplomat for a Weekend", "deck": "A FIWA Student takes on the Model United Nations Stage!", "author": "Ammar Mufiid Johansyah", "body": "\n<p>On the 26th-27th of September, 2026, A Grade 8 Student; Yahya Abdullah Mahmudi, participated in an MUN (Model United Nations) competition. specifically, AYIMUN (Asian Youth International Model United Nations), at it’s Cibubur Chapter.</p>\n<p>For those who aren’t familiar with what MUN is, it’s essentially a competition where students act as diplomats, debating world problems the way real UN delegates do. We asked Yahya if we can say it’s LARPing as the UN. He said yes. So MUN = Larping as UN Members in Debates &amp; stuff.</p>\n<p>Alhamdulillah, he got the award of “Verbal Commendation“, which means he got the 4th place in the competition. The third place is Honorable Mention, the 2nd is Outstanding Delegate, and the 1st is Best Delegate.</p>\n<p>During the MUN Cibubur Chapter (chapter meaning National Versions of MUN instead of the normal international MUNs), the main council that they were representing was ECOSOC &amp; ILO. Yahya specifically was representing the country of the United Kingdom (countries are random).</p>\n<p>Basically, the goal of that competition was to try to agree on a specific solution on 3 problems, in which we don’t know. There were many arguments (obviously), one of the delegates representing Libya for some reason brought the unrelated problem of Taxing Billionaires for state money. You can think about this just a little longer and understand the argument being made and how unnecessary it most likely is.</p>\n<p>If you are interested in MUN, there are a few more things for you to know. One of them is that you Must have a strong foundation in Diniyah, because there you will be exposed to a very diverse enviroment and lots of ideologies as well, so to protect yourself agains the Syubhats &amp; Shahwats, you gotta have a strong foundation. Other than that though, if you do get an MUN certificate, it’s gonna be a big sign that you can lead people when applying for universities and stuff.</p>\n<p>Overall, it’s pretty cool.</p>\n", "edition": 5, "tab": "", "subtab": "", "visibility": "public", "lang": "en"}$fitr$::jsonb, to_timestamp(1792543620000/1000.0), to_timestamp(1793264611718/1000.0)),
  ('articles', 'demo-ed5-houthis', null, $fitr${"coverAspect": 1.7777777777777777, "coverFit": "crop", "section": "external", "title": "Surge on Riyadh: The Houthis Strike Once More", "deck": "Houthis’ Attacks on Saudi Arabia", "author": "Fathi Rizqi Ramadhan", "coverImage": "/demo/edition-5/riyadh-airport.jpg", "body": "\n<p>On October 10th 2026, the Zaidi sect-influenced paramilitary group of the Houthis from Yemen launched an attack considered as the deadliest attack on Saudi Arabia in more than a decade. Targeting Riyadh's King Khalid International Airport, the attack cost at least 12 lives and wounded more than 300 innocent people.</p>\n<p>This attack adds to the series of uprising movements by the Houthis during the 2026 Iran war. The Houthis, long part of Iran's \"Axis of Resistance\", officially entered the war on the 28th of March 2026, rallying alongside Iran against its opponents: the U.S., Israel, its allies in the West, and Saudi Arabia. However, this is just the tip of the iceberg. Their history of rebellion against the West and the Sunni understanding of the Wahhabi dates way back, decades ago.</p>\n<h3>What Should We Do?</h3>\n<p>To put it simply; The Most Important Thing We Can Do is Pray. Pray for our brothers and sisters in Yemen and Saudi who got hit by the attacks, and pray for the Houthi Shi’a to get Hidayah.</p>\n<p><i>*Photo of the Attack on Riyadh’s King Khalid International Airport, on a Smartphone.</i></p>\n<p><i>Source: Al Jazeera, PBS, TIME</i></p>\n<p><i>[Placeholder: the full story is in Edition 5.]</i></p>\n", "edition": 5, "tab": "new-1793264611685-q7l4j", "subtab": "", "visibility": "public", "lang": "en"}$fitr$::jsonb, to_timestamp(1792543560000/1000.0), to_timestamp(1793264611720/1000.0)),
  ('articles', 'demo-ed5-nobel', null, $fitr${"coverAspect": 1.7777777777777777, "coverFit": "crop", "section": "external", "title": "Prestigious Nobel Prize laureates of 2026!", "deck": "Six prizes and ten laureates, announced in Stockholm and Oslo from 5 to 12 October.", "author": "Muhammad Ziya Ibrahim", "body": "\n<h3>Physics, 6th of October: Francis Halzen</h3>\n<p><i>\"For decisive contributions to the IceCube Neutrino Observatory and the discovery of high-energy neutrinos of astrophysical origin.\"</i></p>\n<p>Halzen is a Belgian-American physicist and professor at the University of Wisconsin–Madison. Halzen’s discovery was indeed highly impactful, such as allowing scientists to capture ghostly, near-massless subatomic particles that travel straight from the edge of the universe without scattering or changing direction. One more massive impact is enabling researchers to trace high-energy neutrinos back to violent extragalactic phenomena; such as blazars, supermassive blackholes, and exploding stars. Allowing humans to study processes that traditional light-based telescopes are impossible to capture.</p>\n<h3>Chemistry, 7th of October: Henri B. Kagan &amp; Kenso Soai</h3>\n<p><i>\"For the discovery of non-linear effects and autocatalysis in asymmetric organic synthesis.\"</i></p>\n<p>Kagan is a French chemist at Université Paris-Sud, and Soai a Japanese chemist at the Tokyo University of Science. The two men solved a century-old mystery regarding homochirality; how living organisms came to exclusively use only one version of mirror image molecules rather than equal mix. Kagan developed new ways to manipulate chemical reactions to create a strong excess of one mirror-image form over another through asymmetric catalysis. Kenso Soai discovered asymmetric Autocatalysis (known as Soai reaction). Their work has a massive impact on designing pharmaceuticals, fragrances, agrochemicals, and understanding the chemical origin of life that's been a mystery whose answers vary from various people around the world.</p>\n<h3>Physiology or Medicine, 5th of October: Karl Deisseroth, Peter Hegemann &amp; Georg Nagel</h3>\n<p><i>\"For their discoveries concerning light-gated ion channels and Optogenetics.\"</i></p>\n<p>Deisseroth is an American psychiatrist and bioengineer at Stanford University, Hegemann a German biophysicist and professor of neuroscience at Humboldt University of Berlin, and Nagel a German biophysicist at the University of Würzburg. Optogenetics is a revolutionary technique that allows scientists to control specific nerve cells using light, helping researchers study brain circuits and conditions like Parkinson's disease, depression, and Alzheimer’s disease. Three of the laureates each receive an equal one-third share of the twelve million Swedish Kronor prize.</p>\n<h3>Economic Sciences, 12th of October: Robert E. Hall &amp; Michael Woodford</h3>\n<p><i>“For microeconomic foundations of macroeconomic stabilisation”</i></p>\n<p>Hall is a professor at Stanford University, and Woodford at Columbia University. Instead of relying purely on historical statistical correlations between broad variables, Hall and Woodford built macroeconomic models directly on microeconomic foundations. They demonstrated that when central banks and governments clearly communicate their future policy intentions, they can actively shape public expectations and steer the economy. Central banks and finance ministries worldwide use these models to design better-timer monetary and fiscal policies. The models have proved vital in helping the global economy navigate major modern disruptions, including financial crises, the COVID-19 pandemic fallout, and subsequent energy shocks.</p>\n<p><i>[Placeholder: Peace (Navi Pillay) and Literature (Anne Carson) are on page 11 of Edition 5.]</i></p>\n", "edition": 5, "tab": "new-1793264611685-q7l4j", "subtab": "", "visibility": "public", "lang": "en"}$fitr$::jsonb, to_timestamp(1792543500000/1000.0), to_timestamp(1793264611723/1000.0)),
  ('articles', 'demo-ed5-el-nino', null, $fitr${"coverAspect": 1.7777777777777777, "coverFit": "letterbox", "section": "external", "title": "Earth on Its Highest Boiling Point: The Super El Niño", "deck": "This year's El Niño is on track to be the strongest since records began in 1950, and its effects are already reaching Indonesia.", "author": "Muhammad Ziya Ibrahim", "coverImage": "/demo/edition-5/el-nino-sst.jpg", "body": "\n<p>The Godzilla El Niño is currently on track to be the strongest El Niño of all time. The Japan Meteorology Agency (JMA) and the National Oceanic and Atmospheric Administration (NOAA) expect this year’s El Niño to be the strongest since recording started in 1950.</p>\n<p>In October 2026, the temperature of sea surface in the Pacific territory (Niño 3.4) surpassed 30.06°C, the first time in history to exceed the limit line of 30 degree celsius. The phenomenon is predicted to reach its peak in December 2026 with an anomalous temperature reaching up to +3.7°C above normal.</p>\n<p>The United Nations Children’s Fund (UNICEF) warns that this ‘Super El Niño’ threatens 347 million children in the whole globe for the risk of extreme multiple-at-once weather: extreme drought in several places and severe flash flood in several places.</p>\n<p><i>*Sea-surface temperature anomalies across the entire globe, 11th of October, 2026. The redder the colour, the warmer, and the bluer it is, the colder. The warm band along the equator is El Niño. Source: NOAA.</i></p>\n<p><i>[Placeholder: the full story is in Edition 5.]</i></p>\n", "edition": 5, "tab": "new-1793264611685-cwc4v", "subtab": "", "visibility": "public", "lang": "en"}$fitr$::jsonb, to_timestamp(1792543440000/1000.0), to_timestamp(1793264611728/1000.0)),
  ('articles', 'demo-ed5-ammonia', null, $fitr${"coverAspect": 1.7777777777777777, "coverFit": "crop", "section": "external", "title": "Turning Ammonia Into Hydrogen", "deck": "SO SCIENTISTS FOUND OUT THAT WE CAN TRANSFORM TOXIC AMMONIA INTO USEFUL HYDROGEN OMG.", "author": "Aldebaran Gibran Altaf & Tubagus Attariza Rayyan Athaya", "coverImage": "/demo/edition-5/ammonia-hydrogen.jpg", "body": "\n<p>The research was funded by the U.S. National Science Foundation. MIT researchers have found a more efficient way to turn ammonia to hydrogen using electricity. Previously, this needed high temperatures and extra purification. The new electrochemical method makes the process simpler and produces high-purity hydrogen with less energy.</p>\n<p>This approach uses a palladium-based membrane and molten hydroxide electrolyte (what is that anyway) to separate hydrogen from ammonia. The membrane selectively transports hydrogen, creating a concentrated stream without further purification. It operates at 200 to 300 degrees Celsius, much lower than the previous 500 degrees Celsius requirement, saving energy.</p>\n<p>The method was also applied to methylcyclohexane (try to say that!), another hydrogen carrier, showing potential for transportation and semiconductor manufacturing. Despite the high cost of palladium, researchers aim to reduce its use and scale up the process. (I knew it there’s always a catch)</p>\n<p>This study shows the potential of electrochemical methods to improve hydrogen extraction and storage, advancing the hydrogen economy. This could lead to cleaner energy solutions and better industrial processes.</p>\n<p><i>*Image of Ammonia (left) and Hydrogen (right)</i></p>\n", "edition": 5, "tab": "new-1793264611685-cit3b", "subtab": "", "visibility": "public", "lang": "en"}$fitr$::jsonb, to_timestamp(1792543380000/1000.0), to_timestamp(1793264611729/1000.0)),
  ('articles', 'demo-ed5-orionids', null, $fitr${"coverAspect": 1.7777777777777777, "coverFit": "crop", "section": "external", "title": "Meteor showers at the end of October; A Magnificent sight on a Majestic Night.", "deck": "The Orionids peak before subuh on the 21st–22nd of October, and World Space Week explained.", "author": "Fathan Assyauqi Hiliry", "coverImage": "/demo/edition-5/orionids.jpg", "body": "\n<p>Earlier this year, we watched Halley's comet's smaller debris during the Eta Aquarid Meteor Shower. Now, another meteor shower from the same comet is about to come: the Orionids. The meteors will pass before subuh. Perfect to sleep early, then sip a coffee while watching the stars. The shower has already started (since the 2nd of October), but the peak of the rain will be before subuh on the 21st–22nd of October.</p>\n<h3>Fun Facts:</h3>\n<ul>\n<li>It can be seen from both the southern hemisphere and the northern hemisphere. So all people around the world could watch it.</li>\n<li>The speed of the meteors is very fast, around 66 km/s, leaving glowing trails and sometimes a fireball. The trails can stay in the sky for a few seconds.</li>\n<li>At the peak, you can see around 15–25 meteors per hour under a dark sky.</li>\n</ul>\n<p>A binocular scope won’t help, because it only shows a small part of the sky. So, use your eyes and wait for the spectacular meteors to fly across the field of stars.</p>\n<p>Also, Google featured a Doodle on the 6th of October about World Space Week. And many of us were confused by that. Well, this event is the largest annual space event, and it celebrates the first time ever humans launched a satellite and explored space, with Sputnik 1 from the USSR (4th of October 1957), and the signing of the Outer Space Treaty (10th of October 1967).</p>\n<p>This year's theme was \"Rocket Revolution\". They've held many engineering workshops, webinars about rocketry science and space physics, and developed access for adolescents to find out more about space.</p>\n<p><i>*Photograph of the Orionids Meteor Shower last year</i></p>\n", "edition": 5, "tab": "new-1793264611685-cit3b", "subtab": "", "visibility": "public", "lang": "en"}$fitr$::jsonb, to_timestamp(1792543320000/1000.0), to_timestamp(1793264611731/1000.0)),
  ('articles', 'demo-ed5-f1', null, $fitr${"coverAspect": 1.7777777777777777, "coverFit": "crop", "section": "external", "title": "Triple-Header, All Asia, Extreme climates? Must be an experience.", "deck": "Baku, Sepang and Singapore: three races in a row.", "author": "Fathan Assyauqi Hiliry", "coverImage": "/demo/edition-5/f1-singapore.jpg", "body": "\n<p>A triple-header on started on Baku with the hardest braking spot 90 degree turn to the left. Everything went smooth at Turn 1, yet. Lap by lap, crash by crash. Especially on lap 36 after VSC restart (Albon’s crash). Colapinto did a lockup, drifting into 3 cars. And making them DNF.</p>\n<p>In the final stint Verstappen is chasing Russell with his 5 Major Upgrades with his car for 12 laps. Lap 51, Bottas run wide, at the end of sector 2. Triggering a yellow flag Russell lIft- and coast too long, decreasing the gap between Max. And Sector 3 is the real battle of wins. Russell still defend perfecty and won with the closest gap over 24 years. Also the most DNF on season 2026. Both of them are happy for the fight and happily live, till next race.</p>\n<p>The International war cancelled a frustating Bahrain and Saudi Arabia GP. But it brings one of the race into one of the most forgotten circuits. Yes, Sepang. The climate is how a driver’s nightmare must be. High temperature and humid plus aggressive tyre degradation. The raced on Malaysia was delayed due to heavy rainstorms for 1 hour and 40 minutes.</p>\n<p>The Ferrari’s immediately fall into the backmarker’s place with the soft, while Lawson is chasing Max for P3.</p>\n<p>Let’s just jump into the “Final 5 Laps”. Max is back at P1, Kimi Antonelli on his rear (back). Russell sudden DNF causes Safety Car to occur, making the pack of cars less than a second on Lap 54. Piastri and Lawson fighting for P7. Max finally won his first GP, and the Ferraris? Trace them up.</p>\n<p>The last race of triple-header ended on Singapore, inviting so many “duality” happening. Max (how many times I’ve typed him) starting from the first, tailed by the Ferraris. On Lap 1, Leclerc could almost gain advantage by using inside line, but Max squeezed him up until Leclerc was enforced to brake early, letting max to pass by. You see Max dominate? No, he could barely do coms with his race engineer. Then the Ferrari kept the place until Lewis did a lock-up, making Antonelli climb up to 2 places. And finally, after 10 years driving on the aspal of Marina Bay, Max Verstappen finally won it after 10 years.</p>\n<p>This GP make it more special with Nico’s point finish and Hadjar gain positions for 12 times till P10</p>\n<p><i>*Photograph of Max vs Leclerc on Lap 1, Turn 1</i></p>\n", "edition": 5, "tab": "new-1793264611686-26edz", "subtab": "", "visibility": "public", "lang": "en"}$fitr$::jsonb, to_timestamp(1792543260000/1000.0), to_timestamp(1793264611732/1000.0))
